SELECT 
FROM energy_data
WHERE deleted = 0

    AND park_id = #{query.parkId}


    AND building_id = #{query.buildingId}


    AND floor = #{query.floor}


    AND energy_type = #{query.energyType}


    AND device_id = #{query.deviceId}


    AND collect_time >= #{query.startTime}


    AND collect_time <= #{query.endTime}


    AND status = #{query.status}

ORDER BY ${query.orderBy} ${query.orderDirection}
LIMIT #{query.pageNum}, #{query.pageSize}

SELECT IFNULL(SUM(energy_value), 0)
FROM energy_data
WHERE deleted = 0

    AND park_id = #{parkId}


    AND building_id = #{buildingId}


    AND energy_type = #{energyType}


    AND collect_time >= #{startTime}


    AND collect_time <= #{endTime}

SELECT
    DATE_FORMAT(collect_time, '%Y-%m-%d %H:00:00') AS time_point,
    IFNULL(SUM(energy_value), 0) AS total_energy
FROM energy_data
WHERE deleted = 0

    AND park_id = #{parkId}


    AND energy_type = #{energyType}


    AND collect_time >= #{startTime}


    AND collect_time <= #{endTime}

GROUP BY time_point
ORDER BY time_point ASC

SELECT
    DATE_FORMAT(collect_time, '%Y-%m-%d') AS time_point,
    IFNULL(SUM(energy_value), 0) AS total_energy
FROM energy_data
WHERE deleted = 0

    AND park_id = #{parkId}


    AND energy_type = #{energyType}


    AND collect_time >= #{startTime}


    AND collect_time <= #{endTime}

GROUP BY time_point
ORDER BY time_point ASC

SELECT
    DATE_FORMAT(collect_time, '%Y-%m') AS time_point,
    IFNULL(SUM(energy_value), 0) AS total_energy
FROM energy_data
WHERE deleted = 0

    AND park_id = #{parkId}


    AND energy_type = #{energyType}


    AND collect_time >= #{startTime}


    AND collect_time <= #{endTime}

GROUP BY time_point
ORDER BY time_point ASC
